require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin','staff']);verify_csrf();$db=db();$error='';$doctorOptions=$db->query("SELECT d.id,u.name,d.specialization,dep.name department_name FROM doctors d JOIN users u ON u.id=d.user_id JOIN departments dep ON dep.id=d.department_id WHERE u.status='active' ORDER BY u.name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$name=post_string('name',150);$phone=post_string('phone',50);$email=strtolower(post_string('email',150));$dob=post_string('dob',10);$gender=post_string('gender',10);$blood=post_string('blood_group',10);$address=post_string('address',2000);$doctorId=filter_input(INPUT_POST,'assigned_doctor_id',FILTER_VALIDATE_INT);$doctorId=$doctorId && $doctorId>0 ? (int)$doctorId : null;$doctorExists=false;if($doctorId){$check=$db->prepare("SELECT COUNT(*) FROM doctors d JOIN users u ON u.id=d.user_id WHERE d.id=? AND u.status='active'");$check->execute([$doctorId]);$doctorExists=(bool)$check->fetchColumn();}if(!$name||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob)||!in_array($gender,['Male','Female','Other'],true)||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||!$doctorId||!$doctorExists)$error='Enter valid patient details and select an active doctor.';else{try{$num='PAT-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(3)));$ins=$db->prepare('INSERT INTO patients(user_id,assigned_doctor_id,patient_number,date_of_birth,gender,blood_group,address,full_name,email,phone) VALUES(NULL,?,?,?,?,?,?,?,?,?)');$ins->execute([$doctorId,$num,$dob,$gender,$blood,$address,$name,$email?:null,$phone]);$pid=(int)$db->lastInsertId();audit((int)current_user()['id'],'PATIENT_CREATED','patients',(string)$pid,'Walk-in patient record created; assigned doctor ID: '.($doctorId??'none'));flash('success','Patient registered. Patient ID: '.$num.($doctorId?' and assigned to the selected doctor.':' (no doctor assigned).').' This walk-in record does not create a portal login.');redirect('patients/index.php');}catch(Throwable $ex){error_log('Patient registration error: '.$ex->getMessage());$error='Could not save patient. Please ensure the database assignment migration has been applied.';}}}
$pageTitle='Register patient';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Patient intake','Register a patient','Create a patient record for a new or walk-in patient.');?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card"><div class="card-body"><form method="post" data-disable-submit><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Full name *</label><input class="form-control" name="name" required maxlength="150"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" maxlength="50"></div><div class="col-md-6"><label class="form-label">Email (optional)</label><input class="form-control" type="email" name="email"><div class="form-text">For a portal login, the patient should use the public Patient Registration page.</div></div><div class="col-md-6"><label class="form-label">Assign to doctor *</label><select class="form-select" name="assigned_doctor_id" required><option value="">Select doctor</option><?php foreach($doctorOptions as $doctor):?><option value="<?= (int)$doctor['id']?>" <?=((string)($_POST['assigned_doctor_id']??'')===(string)$doctor['id'])?'selected':''?>><?=e($doctor['name'])?> — <?=e($doctor['specialization'])?> (<?=e($doctor['department_name'])?>)</option><?php endforeach;?></select><?php if(!$doctorOptions):?><div class="form-text text-danger">No active doctors available. Add/activate a doctor first.</div><?php else:?><div class="form-text">After saving, this patient will appear on the selected doctor’s dashboard.</div><?php endif;?></div><div class="col-md-3"><label class="form-label">Date of birth *</label><input class="form-control" type="date" name="dob" max="<?=date('Y-m-d')?>" required></div><div class="col-md-3"><label class="form-label">Gender *</label><select class="form-select" name="gender" required><option value="">Select</option><option>Female</option><option>Male</option><option>Other</option></select></div><div class="col-md-4"><label class="form-label">Blood group</label><select class="form-select" name="blood_group"><option value="">Not recorded</option><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $b):?><option><?=e($b)?></option><?php endforeach;?></select></div><div class="col-md-8"><label class="form-label">Address</label><input class="form-control" name="address" maxlength="2000"></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary">Save patient</button><a class="btn btn-light" href="<?=e(url('patients/index.php'))?>">Cancel</a></div></form></div></div><?php require __DIR__.'/../includes/footer.php';?>